import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def poly_derivative(xs: list):
    """
    Computes the derivative of the polynomial with coefficients xs.
    """
    return [coeff * i for i, coeff in enumerate(xs) if i > 0]

def find_zero(xs: list):
    """
    xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    Returns only one zero point, even if there are many.
    """
    def poly_deriv(x):
        return sum([coeff * i * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    # Initial guess using the largest coefficient index
    max_coeff_idx = max(range(len(xs)), key=lambda i: abs(xs[i]))
    x = max_coeff_idx / 2

    # Newton's method with fallback to bisection
    for _ in range(100):
        fx = poly(xs, x)
        if abs(fx) < 1e-10:
            return x
        dfx = poly_deriv(xs, x)
        if abs(dfx) < 1e-10:
            # Avoid division by zero, use bisection
            break
        x_new = x - fx / dfx
        # Step size limit to prevent divergence
        if abs(x_new - x) < 1e-10:
            return x
        x = x_new
        # If step is too large, switch to bisection
        if abs(x_new - x) > max(1, len(xs)):
            # Use bisection to find a sign change
            a, b = x - 1, x + 1
            for _ in range(100):
                if poly(xs, a) * poly(xs, b) < 0:
                    mid = (a + b) / 2
                    if poly(xs, mid) == 0:
                        return mid
                    if poly(xs, a) * poly(xs, mid) < 0:
                        b = mid
                    else:
                        a = mid
                else:
                    a -= 0.1
                    b += 0.1
                    if abs(poly(xs, a) * poly(xs, b)) < 1e-10:
                        return (a + b) / 2
                if abs(b - a) < 1e-10:
                    return (a + b) / 2
            return (a + b) / 2
    return x
