    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    def poly_derivative(xs, x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    def newton_raphson(xs, x0, tolerance=1e-7, max_iter=1000):
        x = x0
        for _ in range(max_iter):
            fx = poly(xs, x)
            fpx = poly_derivative(xs, x)
            if abs(fpx) < 1e-10:
                break
            x_new = x - fx / fpx
            if abs(x_new - x) < tolerance:
                return x_new
            x = x_new
        return x

    # Find a starting point using bisection to locate a sign change
    def find_sign_change(xs):
        # Search in a reasonable range
        left, right = -1000.0, 1000.0
        for _ in range(100):
            if poly(xs, left) * poly(xs, right) <= 0:
                return left, right
            left *= 2
            right *= 2
        return -1.0, 1.0

    left, right = find_sign_change(xs)
    # Use bisection to find a root
    for _ in range(100):
        mid = (left + right) / 2
        if poly(xs, left) * poly(xs, mid) <= 0:
            right = mid
        else:
            left = mid
    return round(mid, 7)

