def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = sorted(lst)
    result = []
    left = 0
    right = len(sorted_lst) - 1

    while left <= right:
        if left == right:
            result.append(sorted_lst[left])
            break
        elif len(result) % 2 == 0:
            # Even position in result: take minimum from left
            result.append(sorted_lst[left])
            left += 1
        else:
            # Odd position in result: take maximum from right
            result.append(sorted_lst[right])
            right -= 1

    return result

