def count_nums(arr):
    def sum_signed_digits(n):
        if n == 0:
            return 0

        is_negative = n < 0
        n = abs(n)

        # Extract all digits
        digits = []
        while n > 0:
            digits.append(n % 10)
            n //= 10

        # Reverse to get most significant first
        digits = digits[::-1]

        digit_sum = 0
        for i, digit in enumerate(digits):
            if i == 0:  # Most significant digit
                digit_sum -= digit if is_negative else digit
            else:
                digit_sum += digit

        return digit_sum

    count = 0
    for num in arr:
        if sum_signed_digits(num) > 0:
            count += 1
    return count

