from collections import Counter

def is_sorted(lst):
    '''
    Given a list of numbers, return whether or not they are sorted
    in ascending order. If list has more than 1 duplicate of the same
    number, return False. Assume no negative numbers and only integers.
    '''
    if not lst:
        return True

    # Check if list is sorted in ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    # Check if any number appears more than 2 times
    counts = Counter(lst)
    for count in counts.values():
        if count > 2:
            return False

    return True

def is_prime(n):
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def intersection(interval1, interval2):
    """
    Determine whether the length of intersection of two intervals is a prime number.

    Each interval is a pair of integers (start, end), inclusive.
    Returns "YES" if intersection length is prime, "NO" otherwise.
    """
    start1, end1 = interval1[0], interval1[1]
    start2, end2 = interval2[0], interval2[1]

    # Find the intersection bounds
    inter_start = max(start1, start2)
    inter_end = min(end1, end2)

    # Calculate the length of the intersection
    length = inter_end - inter_start

    # If no intersection or length is zero or negative, return "NO"
    if length <= 0:
        return "NO"

    # Check if the length is a prime number
    if is_prime(length):
        return "YES"
    else:
        return "NO"

