def tri(n):
    if n == 0:
        return [1.0]

    # Compute up to n+1 if n is odd (since odd indices need n+1)
    max_idx = n + 1 if n % 2 == 1 else n

    result = [0.0] * (max_idx + 1)
    result[0] = 1.0
    if n >= 1:
        result[1] = 3.0

    # Compute even indices first
    for i in range(2, max_idx + 1, 2):
        result[i] = 1 + i / 2

    # Compute odd indices (they depend on even indices)
    for i in range(3, max_idx + 1, 2):
        result[i] = result[i-1] + result[i-2] + result[i+1]

    return result[:n+1]

