def bell_number(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return 1

    bell = [0] * (n + 1)
    bell[0] = 1

    for i in range(1, n + 1):
        bell[i] = sum(comb(i - 1, k) * bell[k] for k in range(i))

    return bell[n]

