def comb_sort(arr):
    n = len(arr)
    gap = n
    shrink_factor = 1.3

    while gap > 1:
        gap = int(gap / shrink_factor)
        swapped = False
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
        if not swapped:
            break

    # Final pass with gap=1 (Bubble Sort) to ensure full sorting
    gap = 1
    swapped = True
    while swapped:
        swapped = False
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

# Test assertion
assert comb_sort([5, 15, 37, 25, 79]) == [5, 15, 25, 37, 79]

