def eulerian_num(n, m):
    """
    Compute the Eulerian number A(n, m), which counts the number of permutations
    of {1, 2, ..., n} with exactly m ascents.

    Args:
        n (int): Non-negative integer representing the size of the permutation
        m (int): Non-negative integer representing the number of ascents

    Returns:
        int: The Eulerian number A(n, m)
    """
    if n < 0 or m < 0 or m > n:
        return 0

    if n == 0 and m == 0:
        return 1

    # Use memoization to store computed values
    memo = {}

    def helper(n, m):
        if m < 0 or m > n:
            return 0
        if n == 0 and m == 0:
            return 1
        if (n, m) in memo:
            return memo[(n, m)]

        # Recurrence: A(n, m) = (n - m) * A(n-1, m-1) + (m + 1) * A(n-1, m)
        result = (n - m) * helper(n - 1, m - 1) + (m + 1) * helper(n - 1, m)
        memo[(n, m)] = result
        return result

    return helper(n, m)


# Test the function with the provided assertion
assert eulerian_num(3, 1) == 4

