def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        if mid % 2 == 0:
            # If mid is even, arr[mid] should equal arr[mid + 1] in a normal pair
            if arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            # If mid is odd, arr[mid] should equal arr[mid - 1] in a normal pair
            if arr[mid] == arr[mid - 1]:
                left = mid + 1
            else:
                right = mid

    return arr[left]

