    if n <= 1:
        return 0
    total = 1  # 1 is always a proper divisor for n > 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def amicable_numbers_sum(n):
