def find_solution(a, b, n):
    """
    Find integers x and y such that ax + by = n.
    Returns a tuple (x, y) if a solution exists, None otherwise.
    """
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    # Extended Euclidean Algorithm
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            g, x, y = extended_gcd(b % a, a)
            return g, y - (b // a) * x, x

    g, x0, y0 = extended_gcd(a, b)

    # Check if solution exists
    if n % g != 0:
        return None

    # Scale the solution to match n
    x = x0 * (n // g)
    y = y0 * (n // g)

    return (x, y)

