def is_majority(arr, n, element):
    # Find first occurrence using binary search
    def find_first(arr, target):
        left, right = 0, len(arr) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                result = mid
                right = mid - 1  # Look for earlier occurrence
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    # Find last occurrence using binary search
    def find_last(arr, target):
        left, right = 0, len(arr) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                result = mid
                left = mid + 1  # Look for later occurrence
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    first = find_first(arr, element)
    last = find_last(arr, element)

    if first == -1:
        return False  # Element not found

    count = last - first + 1
    return count > n // 2
