def get_total_number_of_sequences(m, n):
    """
    Find the number of possible sequences of length n where:
    - Each element is a positive integer
    - Each element is >= 2 * previous element
    - Each element is <= m
    """
    if n <= 0 or m <= 0:
        return 0

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_sequences(index, min_val):
        if index == n:
            return 1

        total = 0
        # Try all possible values for current position
        for val in range(min_val, m + 1):
            # Check if val >= 2 * previous element
            if val >= 2 * min_val:
                total += count_sequences(index + 1, val)

        return total

    return count_sequences(1, 1)

# Test the function
assert get_total_number_of_sequences(10, 4) == 4
