def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the most significant bit position
    msb = n.bit_length() - 1

    # Find the leftmost unset bit (highest position with 0)
    for i in range(msb, -1, -1):
        if not (n & (1 << i)):
            return n | (1 << i)

    # If all bits are set, add a new bit at the next position
    return n + (1 << (msb + 1))


