def set_left_most_unset_bit(n: int) -> int:
    """
    Set the leftmost unset bit (leftmost 0) of the given number.

    Args:
        n: A non-negative integer

    Returns:
        Integer with the leftmost unset bit set to 1
    """
    if n == 0:
        return 1

    highest_bit = n.bit_length()

    for i in range(highest_bit - 1, -1, -1):
        if not (n & (1 << i)):
            return n | (1 << i)

    return n | (1 << highest_bit)
