def index_multiplication(t1, t2):
    """
    Performs index-wise multiplication of tuple elements in the given two tuples.
    Each inner tuple in the result is the element-wise product of the corresponding 
    inner tuples from the input tuples.
    """
    return tuple(
        tuple(x * y for x, y in zip(inner1, inner2))
        for inner1, inner2 in zip(t1, t2)
