def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    # dp[i] will store the maximum product of an increasing subsequence ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    # The maximum product is the maximum value in dp array
    return max(dp)


