def bell_Number(n):
    if n == 0:
        return 1

    # Build Bell triangle
    triangle = [[0] * (n + 1) for _ in range(n + 1)]
    triangle[0][0] = 1

    for i in range(1, n + 1):
        triangle[i][0] = triangle[i - 1][i - 1]
        for j in range(1, i + 1):
            triangle[i][j] = triangle[i - 1][j - 1] + triangle[i][j - 1]

    return triangle[n][0]


