def move_num(s):
    non_numbers = []
    numbers = []
    i = 0
    n = len(s)

    while i < n:
        if s[i].isdigit():
            # Collect all consecutive digits
            num = ''
            while i < n and s[i].isdigit():
                num += s[i]
                i += 1
            numbers.append(num)
        else:
            non_numbers.append(s[i])
            i += 1

    return ''.join(non_numbers) + ''.join(numbers)


