def replace_spaces(s):
    """
    Replace whitespaces with underscores and vice versa in a given string.
    - If the string contains spaces but no underscores, replace spaces with underscores.
    - If the string contains underscores but no spaces, replace underscores with spaces.
    - If both exist, replace spaces with underscores (underscores remain unchanged).
    - If neither exists, return the string unchanged.
    """
    if ' ' in s and '_' not in s:
        return s.replace(' ', '_')
    elif '_' in s and ' ' not in s:
        return s.replace('_', ' ')
    elif ' ' in s and '_' in s:
        return s.replace(' ', '_')
    else:
        return s


