def get_pairs_count(nums, target_sum):
    """
    Count the number of pairs whose sum equals the target sum.

    Args:
        nums: List of integers
        target_sum: Target sum for pairs

    Returns:
        Number of pairs whose sum equals target_sum
    """
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    pairs = 0
    for num in count:
        complement = target_sum - num
        if complement in count:
            if num == complement:
                pairs += count[num] * (count[num] - 1) // 2
            elif num < complement:
                pairs += count[num] * count[complement]

    return pairs


