def count_divisors(n):
    """
    Check whether the count of divisors of n is even.
    Returns True if the number of divisors is even, False otherwise.
    """
    if n <= 0:
        return False
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
    return count % 2 == 0

# Test the function
assert count_divisors(10)  # 10 has 4 divisors: 1, 2, 5, 10 → even

